package org.apache.commons.cli;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilder_HasArgsTest {

    private int initialArgCount;

    @BeforeEach
    void setUp() throws Exception {
        // capture initial argCount
        initialArgCount = getArgCount();
        // ensure a clean state before each test by invoking private reset()
        invokeReset();
    }

    @Test
    void testHasArgsSetsArgCountAndReturnsSingletonInstance() throws Exception {
        // given
        int expected = 5;

        // when
        OptionBuilder returned = OptionBuilder.hasArgs(expected);

        // then
        assertNotNull(returned, "hasArgs should not return null");
        assertSame(getInstance(), returned, "hasArgs should return the singleton INSTANCE");
        assertEquals(expected, getArgCount(), "argCount should be set to the provided value");
    }

    @Test
    void testHasArgsOverwritesPreviousValue() throws Exception {
        // set initial
        OptionBuilder.hasArgs(2);
        assertEquals(2, getArgCount(), "precondition: argCount should be 2");

        // overwrite
        OptionBuilder.hasArgs(7);
        assertEquals(7, getArgCount(), "argCount should be overwritten to 7");
    }

    @Test
    void testHasArgsWithZeroAndNegativeValues() throws Exception {
        OptionBuilder.hasArgs(0);
        assertEquals(0, getArgCount(), "argCount should accept zero");

        OptionBuilder.hasArgs(-1);
        assertEquals(-1, getArgCount(), "argCount should accept negative values");
    }

    @Test
    void testResetRestoresInitialArgCount() throws Exception {
        // change value
        OptionBuilder.hasArgs(10);
        assertEquals(10, getArgCount(), "precondition: argCount should be 10");

        // reset and verify
        invokeReset();
        assertEquals(initialArgCount, getArgCount(), "reset should restore the initial argCount");
    }

    // --- Reflection helpers ---

    private static int getArgCount() throws Exception {
        Field argCountField = OptionBuilder.class.getDeclaredField("argCount");
        argCountField.setAccessible(true);
        return argCountField.getInt(null);
    }

    private static OptionBuilder getInstance() throws Exception {
        Field instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);
        return (OptionBuilder) instanceField.get(null);
    }

    private static void invokeReset() throws Exception {
        Method reset = OptionBuilder.class.getDeclaredMethod("reset");
        reset.setAccessible(true);
        reset.invoke(null);
    }
}

